on conflict(source_id) do update set
 source_name=excluded.source_name,provider_name=excluded.provider_name,
 category=excluded.category,access_type=excluded.access_type,
 authentication_type=excluded.authentication_type,base_url=excluded.base_url,
 licence_name=excluded.licence_name,commercial_usage_status=excluded.commercial_usage_status,
 raw_redistribution_allowed=excluded.raw_redistribution_allowed,attribution_required=excluded.attribution_required,
 enabled_for_ingestion=excluded.enabled_for_ingestion,enabled_for_commercial_signals=excluded.enabled_for_commercial_signals,
 country_scope=excluded.country_scope,freshness_class=excluded.freshness_class,notes=excluded.notes,updated_at=now();

create table if not exists public.live_country_critical_mineral_source_directory (
 country_iso2 text primary key,
 rmis_country_profile_url text not null,
 usgs_source_id text not null references public.live_external_sources(source_id),
 bgs_source_id text not null references public.live_external_sources(source_id),
 national_mineral_source_id text,
 source_discovery_state text not null default 'DISCOVERED'
  check(source_discovery_state in ('DISCOVERED','VERIFIED','REJECTED')),
 notes text not null default 'Critical-minerals country inventory. Exact source availability, rights, schema and freshness remain certification-gated.',
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);

