insert into public.live_global_source_universe
(universe_id,scope_type,scope_code,source_role,source_id,priority,required,notes)
select
 'COUNTRY:'||r.iso3||':CRITICAL_RMIS:rmis_country_'||lower(d.country_iso2),
 'COUNTRY',r.iso3,'CRITICAL_MINERALS_COUNTRY_PRIMARY',
 'rmis_country_'||lower(d.country_iso2),10,true,'RMIS country critical-minerals profile.'
from public.live_country_critical_mineral_source_directory d
join public.live_country_registry r on upper(r.iso2)=upper(d.country_iso2)
where r.enabled
on conflict(scope_type,scope_code,source_role,source_id) do update set updated_at=now();

insert into public.live_global_source_universe
(universe_id,scope_type,scope_code,source_role,source_id,priority,required,notes)
select
 'COUNTRY:'||r.iso3||':CRITICAL_USGS:usgs_mcs',
 'COUNTRY',r.iso3,'CRITICAL_MINERALS_GLOBAL_PRIMARY','usgs_mcs',20,true,'USGS mineral production/supply baseline.'
from public.live_country_registry r where r.enabled
on conflict(scope_type,scope_code,source_role,source_id) do update set updated_at=now();

insert into public.live_global_source_universe
(universe_id,scope_type,scope_code,source_role,source_id,priority,required,notes)
select
 'COUNTRY:'||r.iso3||':CRITICAL_BGS:bgs_world_minerals',
 'COUNTRY',r.iso3,'CRITICAL_MINERALS_GLOBAL_SECONDARY','bgs_world_minerals',30,true,'BGS country-by-country mineral production baseline.'
from public.live_country_registry r where r.enabled
on conflict(scope_type,scope_code,source_role,source_id) do update set updated_at=now();

insert into public.live_global_source_universe
(universe_id,scope_type,scope_code,source_role,source_id,priority,required,notes)
select
 'COUNTRY:'||r.iso3||':CRITICAL_NATIONAL:'||d.national_mineral_source_id,
 'COUNTRY',r.iso3,'CRITICAL_MINERALS_NATIONAL',d.national_mineral_source_id,5,true,
 'Dedicated national mineral/geoscience source candidate.'
from public.live_country_critical_mineral_source_directory d
join public.live_country_registry r on upper(r.iso2)=upper(d.country_iso2)
where r.enabled and d.national_mineral_source_id is not null
on conflict(scope_type,scope_code,source_role,source_id) do update set updated_at=now();

